// ── Request ID middleware ───────────────────────────────────────────
// Accepts an inbound X-Request-ID (so frontend / proxy can supply one) or
// generates a fresh UUID. Echoed back on the response so the user can quote
// it in a support ticket and we can grep logs for that exact request.
app.use('*', async (c, next) => {
  const inbound = c.req.header('x-request-id') || c.req.header('X-Request-ID');
  const reqId = inbound && /^[A-Za-z0-9._-]{8,128}$/.test(inbound) ? inbound : crypto.randomUUID();
  c.set('requestId', reqId);
  c.header('X-Request-ID', reqId);
  await next();
});

// Global Error Handler to prevent crashes
app.onError((err, c) => {
  // Client disconnections are expected (SSE close, navigation, aborted fetches) — ignore
  const msg = err?.message || '';
  if (isConnectionClosedMsg(msg) || err?.name === 'Http' || err?.name === 'AbortError') {
    return c.text('', 499 as any);
  }
  // Forward auth errors with their proper status code (401) so the frontend
  // can trigger token refresh instead of treating them as server crashes.
  const status = (err as any)?.status;
  if (status && status >= 400 && status < 500) {
    return c.json({ error: err.message }, status);
  }
  console.error('🔥 Global Server Error:', err);
  // Never expose stack traces to clients — log them server-side only
  return c.json({ 
    error: "Internal Server Error", 
    message: err.message
  }, 500);
});

// Global Not Found Handler
app.notFound((c) => {
  return c.json({ error: "Endpoint not found", path: c.req.path }, 404);
});

