// The cors() middleware handles OPTIONS preflights automatically.
// A separate app.options('*') handler was removed because it was overriding
// the cors middleware response, stripping CORS headers from preflights.

// Helper: Create an error with an HTTP status so catch blocks can return the
// correct status code instead of a blanket 500. Auth failures → 401.
function authError(message: string, status = 401): Error {
  const err = new Error(message);
  (err as any).status = status;
  return err;
}

// Helper: check whether an error is an auth/401 error thrown by authError() or getAuthenticatedUser()
function isAuthError(err: any): boolean {
  if (err?.status === 401) return true;
  const msg = err?.message || '';
  return msg.includes('Authentication failed') || msg.includes('Session expired')
    || msg.includes('No Authorization header') || msg.includes('Invalid Authorization header');
}

// Helper: Get authenticated user (uses singleton admin client)
async function getAuthenticatedUser(c: any) {
  const authHeader = c.req.header('Authorization');
  if (!authHeader) {
    throw authError("Authentication failed: No Authorization header");
  }

  // Extract the JWT token from "Bearer TOKEN" format
  const token = authHeader.replace('Bearer ', '').trim();
  if (!token || token === authHeader || token === 'undefined' || token === 'null') {
    throw authError("Authentication failed: Invalid Authorization header format");
  }

  // Use singleton service role client
  const supabase = getSupabaseAdmin();

  // ── Service-key impersonation (for cron / internal calls) ──
  // If the token matches the service role key AND the X-Cron-As-User header is set,
  // look up that user via admin API instead of JWT auth. This lets the cron system
  // call authenticated endpoints on behalf of any user without needing their JWT.
  const serviceKey = (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '').trim();
  const cronAsUser = c.req.header('X-Cron-As-User');
  if (serviceKey && token.trim() === serviceKey && cronAsUser) {
    try {
      const { data, error } = await supabase.auth.admin.getUserById(cronAsUser);
      if (error) throw error;
      if (!data?.user) throw new Error('User not found');
      console.log(`[AUTH] Service-key impersonation for user ${data.user.email} (cron)`);
      return { user: data.user, supabase };
    } catch (err: any) {
      console.error('[AUTH] Service-key impersonation failed:', err.message);
      throw authError(`Cron impersonation failed: ${err.message}`);
    }
  }
  
  // Verify the user's JWT token (with retry for transient connection resets)
  let user;
  const AUTH_MAX_RETRIES = 5;
  const AUTH_TIMEOUT_MS = 15000; // 15s timeout for auth operations
  for (let _authAttempt = 0; _authAttempt < AUTH_MAX_RETRIES; _authAttempt++) {
    try {
      // Re-fetch client each attempt so resetSupabaseAdmin() takes effect
      const client = getSupabaseAdmin();
      
      // Wrap auth call with timeout protection
      const result = await Promise.race([
        client.auth.getUser(token),
        new Promise<never>((_, reject) => 
          setTimeout(() => reject(new Error('Auth timeout after 15000ms')), AUTH_TIMEOUT_MS)
        )
      ]);
      
      if (result.error) throw result.error;
      user = result.data.user;
      recordConnectionSuccess(); // Track successful auth
      break; // success
    } catch (err) {
      const msg = err?.message ?? String(err);
      
      // AbortSignal errors = client cancelled request (navigation, timeout, etc.)
      // These are NOT recoverable network errors, so don't retry
      const isAbortError = msg.includes('signal is aborted') || msg.includes('aborted without reason')
        || msg.includes('operation was aborted') || msg.includes('The operation was aborted');
      if (isAbortError) {
        console.debug(`[AUTH] Request aborted by client (navigation/timeout) — ${msg}`);
        throw authError('Request aborted');
      }
      
      // Check if this is a transient network error worth retrying
      const isTransientNetwork = msg.includes('connection reset') || msg.includes('error sending request')
        || msg.includes('ECONNRESET') || msg.includes('os error 104')
        || msg.includes('broken pipe') || msg.includes('network error')
        || msg.includes('connection unexpectedly') || msg.includes('client error')
        || msg.includes('SendRequest') || msg.includes('ConnectionAborted')
        || msg.includes('connection closed before message completed')
        || msg.includes('schema cache') || msg.includes('PGRST002')
        || msg.includes('Database error querying schema') || msg.includes('Unexpected failure')
        || msg.includes('fetch failed') || msg.includes('Failed to fetch')
        || msg.includes('tls handshake') || msg.includes('close_notify')
        || msg.includes('peer closed connection') || msg.includes('Auth timeout')
        || msg.includes('eof');
      if (isTransientNetwork && _authAttempt < AUTH_MAX_RETRIES - 1) {
        // Track connection errors for health monitoring
        recordConnectionError();
        
        // Reset singleton client so next attempt gets a fresh TCP connection
        resetSupabaseAdmin();
        const jitter = Math.random() * 200;
        const delay = 400 * Math.pow(2, _authAttempt) + jitter;
        // Only log warning on 2nd+ attempt to reduce noise from normal cold-start slowness
        if (_authAttempt === 0) {
          console.debug(`[AUTH] Network error (attempt ${_authAttempt + 1}/${AUTH_MAX_RETRIES}), retrying in ${Math.round(delay)}ms — ${msg}`);
        } else {
          console.log(`[AUTH] Network error (attempt ${_authAttempt + 1}/${AUTH_MAX_RETRIES}), retrying in ${Math.round(delay)}ms — ${msg}`);
        }
        await new Promise(r => setTimeout(r, delay));
        continue;
      }
      // Suppress "Auth session missing!" logs as they are just expired sessions
      if (msg === 'Auth session missing!') {
         throw authError('Session expired');
      }
      // Suppress expired-token errors — routine, handled by client-side 401 retry
      if (msg.includes('token is expired') || msg.includes('token has expired') || msg.includes('invalid JWT')) {
         throw authError('Session expired');
      }
      // Detect "user deleted but JWT still cached" — needs special handling on the frontend
      if (msg.includes('User from sub claim in JWT does not exist')) {
         console.warn('[AUTH] User no longer exists in Supabase Auth (deleted account). JWT is stale.');
         throw authError('USER_NOT_FOUND: The account associated with this session no longer exists.');
      }
      console.warn('[AUTH] Authentication failed:', msg);
      throw authError(`Authentication failed: ${msg}`);
    }
  }
  
  if (!user) {
    throw authError("Session expired or invalid - please sign in again");
  }

  // Cache email→uid mapping so isAdminEmail() can resolve UIDs automatically
  // even when callers only pass user.email (avoids changing 40+ call sites)
  if (user.email && user.id) {
    _recentEmailToUid.set(user.email.toLowerCase().trim(), user.id);
  }

  // Stash actor identity on the Hono context so audit-log helpers and any
  // request-scoped logging can read it without re-running auth.
  try {
    c.set('userId', user.id);
    c.set('userEmail', user.email || null);
  } catch { /* context.set may not be available in odd code paths */ }

  // ── First-touch waitlist backfill for OAuth orphans ──
  // OAuth signups create the auth.users row via Supabase's callback
  // BEFORE our app-side code runs. If the user bails before completing
  // the /auth/complete-oauth-profile screen, no contndr_sub or waitlist
  // entry exists — they become an invisible orphan. Here, on every auth
  // check, we lazily backfill those records. Once per server instance
  // per user (in-memory dedup) so the cost is negligible.
  if (!_backfillChecked.has(user.id)) {
    _backfillChecked.add(user.id);
    backfillOrphanUser(user).catch((e) => {
      console.warn('[AUTH] Backfill check failed (non-fatal):', e?.message);
    });
  }

  return { user, supabase };
}

// Per-cold-start cache of users we've already backfill-checked.
const _backfillChecked = new Set<string>();

/**
 * If a user has no contndr_sub and no waitlist entry, create a pending
 * waitlist record so they show up in the admin queue. Fire-and-forget,
 * idempotent — safe to call repeatedly.
 */
async function backfillOrphanUser(user: any): Promise<void> {
  if (!user?.id || !user?.email) return;
  try {
    const email = user.email.toLowerCase().trim();
    const [sub, waitlistId] = await Promise.all([
      kv.get(`contndr_sub:${user.id}`).catch(() => null),
      kv.get(`waitlist:email:${email}`).catch(() => null),
    ]);
    // Only backfill if BOTH are missing — never overwrite real data.
    if (sub || waitlistId) return;

    const provider = user.app_metadata?.provider || 'unknown';
    const name = user.user_metadata?.full_name || user.user_metadata?.name || user.user_metadata?.user_name || email.split('@')[0];
    const newWaitlistId = `wl_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

    await Promise.all([
      kv.set(`contndr_sub:${user.id}`, {
        status: 'pending',
        plan: 'waitlist',
        created_at: new Date().toISOString(),
        signup_method: provider,
        backfilled: true,
      }),
      kv.set(`waitlist:${newWaitlistId}`, {
        id: newWaitlistId,
        email,
        name,
        status: 'pending_signup',
        created_at: user.created_at || new Date().toISOString(),
        source: `oauth_${provider}_orphan_backfill`,
        userId: user.id,
      }),
      kv.set(`waitlist:email:${email}`, newWaitlistId),
    ]);

    console.log(`[BACKFILL] Created waitlist entry for OAuth orphan ${email} (${provider})`);
    logAdminEvent('orphan_backfilled', 'OAuth Orphan Detected', `${name} (${email}) created via ${provider} but never completed signup — backfilled to waitlist`, {
      email,
      metadata: { name, provider, user_id: user.id, source: 'auth_first_touch' },
    }).catch(() => {});
  } catch (e: any) {
    console.warn('[BACKFILL] error:', e?.message);
  }
}

// Module-level email→uid cache populated by getAuthenticatedUser().
// Used by isAdminEmail() to auto-resolve admin UIDs when only email is passed.
const _recentEmailToUid = new Map<string, string>();

// Helper: Basic email validation
function isValidBusinessEmail(email: string): boolean {
  if (!email || typeof email !== 'string') return false;
  const emailLower = email.toLowerCase().trim();
  const invalidPatterns = ['placeholder', 'example', 'test'];
  return !invalidPatterns.some(p => emailLower.includes(p));
}

// Decide whether a send-time error message indicates the RECIPIENT'S
// mailbox refused the message (a real bounce that should mark the lead
// as bounced and forbid re-sending) vs. a sender-side problem like auth
// failure, rate limit, network glitch, or provider outage (which should
// NOT mark the lead as bounced — just retry the send later).
//
// Real recipient bounces from SMTP / Gmail / Outlook / Resend share
// specific 5xx phrasings. The previous regex was too loose — words like
// "unknown" and "rejected" appear in many sender-side error strings
// ("Unknown error from Gmail", "API rate limit rejected request"),
// which silently flagged 99/100 of a recent broadcast as bounced.
//
// Conservative rule: must match one of the precise mailbox-rejected
// patterns AND must NOT contain any of the sender-side signal words.
function looksLikeRecipientBounce(errMsg: string | null | undefined): boolean {
  if (!errMsg) return false;
  const msg = String(errMsg).toLowerCase();
  // Sender-side signals — never a recipient bounce.
  if (/\b(auth|token|credential|rate[ -]?limit(?:ed)?|429|timeout|timed out|network|fetch|connect(?:ion)?|tls|ssl|handshake|aborted|api key|unauthor(?:ized|ised)|forbidden|503|502|504|service unavailable|gateway|circuit|insufficient|quota exceeded(?: for sender)?)\b/i.test(errMsg)) {
    return false;
  }
  // Precise recipient-bounce patterns.
  return (
    /\b5\.[157]\.[0-9]\b/.test(msg) ||                               // 5.1.1, 5.7.x SMTP perm-fail codes
    /\b550\b.*(?:no such user|user unknown|mailbox|recipient|address)/i.test(errMsg) ||
    /\brecipient (?:address )?(?:rejected|unknown|not found|does not exist)\b/i.test(errMsg) ||
    /\bmailbox (?:unavailable|does not exist|not found|full|disabled|over quota|invalid)\b/i.test(errMsg) ||
    /\baddress (?:not found|rejected|invalid|does not exist)\b/i.test(errMsg) ||
    /\bno such (?:user|recipient|mailbox|address)\b/i.test(errMsg) ||
    /\buser (?:unknown|does not exist|not found)\b/i.test(errMsg) ||
    /\bemail (?:address )?(?:does not exist|invalid)\b/i.test(errMsg) ||
    /\bundeliverable\b/i.test(errMsg) && /\b(?:recipient|mailbox|address|to)\b/i.test(errMsg)
  );
}

function normalizeIntentPageFromUrl(rawUrl: string | null | undefined): string | null {
  if (!rawUrl) return null;
  try {
    const path = new URL(rawUrl).pathname.toLowerCase();
    if (path.includes('pricing')) return 'pricing';
    if (path.includes('demo') || path.includes('book-call')) return 'demo';
    if (path.includes('contact')) return 'contact';
    if (path.includes('case-study') || path.includes('case_study')) return 'case_study';
    if (path.includes('checkout')) return 'checkout';
  } catch {
    const lower = String(rawUrl).toLowerCase();
    if (lower.includes('pricing')) return 'pricing';
    if (lower.includes('demo') || lower.includes('book-call')) return 'demo';
    if (lower.includes('contact')) return 'contact';
    if (lower.includes('case-study') || lower.includes('case_study')) return 'case_study';
    if (lower.includes('checkout')) return 'checkout';
  }
  return null;
}

async function maybeTriggerAgentHotVisitorCall(args: {
  targetUserId: string | null | undefined;
  lead: any;
  visitData: any;
  supabase: ReturnType<typeof createClient>;
}) {
  const { targetUserId, lead, visitData, supabase } = args;
  try {
    if (!targetUserId) {
      console.log('[AGENT HOT CALL] Skipping visitor: missing target user', { lead_id: lead?.id, url: visitData?.url });
      return;
    }
    if (!lead?.id || lead.id === 'anonymous') {
      console.log('[AGENT HOT CALL] Skipping visitor: anonymous or unresolved lead', { lead_id: lead?.id, url: visitData?.url });
      return;
    }
    if (!lead.phone) {
      console.log('[AGENT HOT CALL] Skipping visitor: lead has no phone', { lead_id: lead.id, email: lead.email, url: visitData?.url });
      return;
    }
    if (!['page_view', 'visit', 'email_click', undefined, null].includes(visitData?.event_type)) {
      console.log('[AGENT HOT CALL] Skipping visitor: unsupported event type', { lead_id: lead.id, event_type: visitData?.event_type });
      return;
    }

    let page = normalizeIntentPageFromUrl(visitData?.url);
    const isEmailClickTrigger = visitData?.source === 'email_click' || visitData?.event_type === 'email_click';
    if (!page && isEmailClickTrigger) page = 'email_click';
    // Don't filter by intent page anymore — any page view from a known
    // lead with a phone counts as a hot signal. The previous logic
    // required the URL to map to a "/pricing", "/demo", "/contact" path,
    // which kicked out most real traffic.
    if (!page) page = 'visit';

    const { data: authUserResult } = await supabase.auth.admin.getUserById(targetUserId).catch(() => ({ data: null } as any));
    const accountUser = authUserResult?.user || { id: targetUserId, email: null };
    const subscription = await getUserSubscriptionStatus(accountUser);
    const entitlements = getPlanEntitlements(subscription?.plan || 'none');
    const config = sanitizeAgentModeConfig(await kvGetSafe(`agent_mode:${targetUserId}:config`), entitlements);
    if (!config.enabled || !config.autoCallHotVisitors || !entitlements.aiCalling) {
      console.log('[AGENT HOT CALL] Skipping visitor: Agent Mode or auto-call toggle disabled', {
        targetUserId,
        plan: subscription?.plan || 'none',
        agent_enabled: config.enabled,
        auto_call_hot_visitors: config.autoCallHotVisitors,
        ai_calling: entitlements.aiCalling,
      });
      return;
    }

    // SIMPLIFIED: don't require a manually-set-up AI call template with
    // intent_trigger configured. That was 5+ clicks of setup before the
    // feature could ever fire. Instead, we use the user's first active
    // AI call campaign (if any) as a SCRIPT SOURCE for branding/agent
    // voice/opening line. If they have none, we use safe defaults that
    // the processor already supports.
    const campaigns = await kv.getByPrefixLimited(`ai-call-campaign:${targetUserId}:`, 250, 0).catch(() => []);
    const scriptSource = (campaigns || []).find((c: any) =>
      c && c.status === 'active' && !String(c.id || '').startsWith('agent-hot-')
    ) || null;

    const now = Date.now();
    // Per-lead cooldown (default 24h) so we never auto-call the same lead
    // twice on rapid repeat visits. Configurable on the Agent Mode config.
    const cooldownHours = Math.min(168, Math.max(1, Number(config.hotVisitorCooldownHours || 24)));

    // ── Multi-dimension dedup keys ──
    // Originally only checked by lead.id, but our visitor tracker creates
    // a NEW anonymous lead row on each unique IP/session, so the same
    // company hits us with multiple lead.ids over time and the cooldown
    // misses. Add secondary dedup on normalized company name, email,
    // domain, and phone. Any of them tripping = skip.
    const normCompany = String(lead.business_name || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 80);
    const normEmail = String(lead.email || '').trim().toLowerCase();
    const normPhone = String(lead.phone || '').replace(/[^\d+]/g, '');
    const normDomain = (() => {
      const raw = String(lead.website || lead.domain || '').toLowerCase();
      try { return new URL(raw.startsWith('http') ? raw : `https://${raw}`).hostname.replace(/^www\./, ''); } catch { return ''; }
    })();
    const dedupKeys = [
      `agent_hot_call_cooldown:${targetUserId}:${lead.id}`,
      normCompany ? `agent_hot_call_cooldown:${targetUserId}:co:${normCompany}` : null,
      normEmail   ? `agent_hot_call_cooldown:${targetUserId}:em:${normEmail}` : null,
      normPhone   ? `agent_hot_call_cooldown:${targetUserId}:ph:${normPhone}` : null,
      normDomain  ? `agent_hot_call_cooldown:${targetUserId}:dn:${normDomain}` : null,
    ].filter(Boolean) as string[];

    for (const key of dedupKeys) {
      const cd = await kvGetSafe<any>(key);
      if (cd?.expires_at && new Date(cd.expires_at).getTime() > now) {
        console.log('[AGENT HOT CALL] Skipping visitor: cooldown active', { key, expires_at: cd.expires_at });
        return;
      }
    }

    // ── Race-safe dedup: claim ALL dedup keys IMMEDIATELY ──
    // Writing the cooldown BEFORE creating the campaign shrinks the race
    // window from "however long createCampaign takes" to "one KV roundtrip".
    // Writing all 5 keys at once means a parallel visit on a different
    // dimension (e.g. same company but different anonymous lead row) also
    // gets blocked.
    const cooldownPayload = {
      lead_id: lead.id,
      business_name: lead.business_name || null,
      template_campaign_id: 'pending',
      queued_at: new Date().toISOString(),
      expires_at: new Date(now + cooldownHours * 60 * 60 * 1000).toISOString(),
    };
    await Promise.all(dedupKeys.map((k) => kvSetSafe(k, cooldownPayload)));

    const dateKey = new Date().toISOString().split('T')[0];
    const dailyKey = `agent_hot_call_daily:${targetUserId}:${dateKey}`;
    const daily = (await kvGetSafe<any>(dailyKey)) || { date: dateKey, count: 0 };
    const maxDailyCalls = Math.min(250, Math.max(1, Number(config.maxDailyActions || 25)));
    if ((daily.count || 0) >= maxDailyCalls) {
      console.log('[AGENT HOT CALL] Skipping visitor: daily cap reached', { targetUserId, date: dateKey, count: daily.count || 0, maxDailyCalls });
      return;
    }

    daily.count = (daily.count || 0) + 1;
    daily.updated_at = new Date().toISOString();
    await kvSetSafe(dailyKey, daily);

    const callCampaignId = `agent-hot-${now}-${crypto.randomUUID().slice(0, 8)}`;
    const hotLead = {
      ...lead,
      business_name: lead.business_name || lead.contact_name || 'Known visitor',
      contact_name: lead.contact_name || lead.business_name || 'Known visitor',
    };
    // Synthetic campaign — built from script source if available, else
    // safe defaults. ai-call-processor.tsx has its own opening-line
    // fallback ("Hey there! This is Alex from Contndr") for empty fields.
    const callCampaign = {
      ...(scriptSource || {}),
      id: callCampaignId,
      parent_campaign_id: scriptSource?.id || null,
      name: `Hot visitor: ${hotLead.business_name}`,
      status: 'active',
      brand: scriptSource?.brand || 'contndr',
      ai_name: scriptSource?.ai_name || 'Alex',
      opening_line: scriptSource?.opening_line || '',
      selected_leads: [hotLead],
      total_leads: 1,
      calls_made: 0,
      in_progress: 0,
      completed_calls: 0,
      trigger_source: 'agent_mode_hot_visitor',
      trigger_visit: {
        id: visitData.id,
        page,
        url: visitData.url,
        campaign_id: visitData.campaign_id,
        email_id: visitData.email_id,
        timestamp: visitData.timestamp,
      },
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    const templateIdForLogs = scriptSource?.id || 'default';

    const campaignKey = `ai-call-campaign:${targetUserId}:${callCampaignId}`;
    const queueKey = `agent_hot_call:${targetUserId}:${now}:${callCampaignId}`;
    await kvSetSafe(campaignKey, callCampaign);
    await kvSetSafe(queueKey, {
      id: callCampaignId,
      status: 'queued',
      template_campaign_id: templateIdForLogs,
      lead_id: lead.id,
      page,
      url: visitData.url,
      queued_at: new Date().toISOString(),
    });
    // Stamp the cooldown with the real template_id (was 'pending' from
    // the race-claim write above). Same TTL; just enriches metadata.
    await kvSetSafe(cooldownKey, {
      lead_id: lead.id,
      template_campaign_id: templateIdForLogs,
      queued_at: new Date().toISOString(),
      expires_at: new Date(now + cooldownHours * 60 * 60 * 1000).toISOString(),
    });
    console.log('[AGENT HOT CALL] Queued hot visitor AI call', { targetUserId, lead_id: lead.id, campaign_id: callCampaignId, template_id: templateIdForLogs, page });

    const work = processAICallCampaign(callCampaignId, targetUserId, callCampaign)
      .then(async () => {
        const finalCampaign = await kvGetSafe<any>(campaignKey);
        await kvSetSafe(queueKey, {
          id: callCampaignId,
          status: finalCampaign?.status || 'processed',
          template_campaign_id: templateIdForLogs,
          lead_id: lead.id,
          page,
          url: visitData.url,
          queued_at: new Date(now).toISOString(),
          processed_at: new Date().toISOString(),
          calls_made: finalCampaign?.calls_made || 0,
          pause_reason: finalCampaign?.pause_reason || null,
        });
      })
      .catch(async (error: any) => {
        await kvSetSafe(queueKey, {
          id: callCampaignId,
          status: 'failed',
          template_campaign_id: templateIdForLogs,
          lead_id: lead.id,
          page,
          url: visitData.url,
          queued_at: new Date(now).toISOString(),
          failed_at: new Date().toISOString(),
          error: String(error?.message || error).slice(0, 500),
        });
      });

    try {
      if (typeof EdgeRuntime !== 'undefined' && EdgeRuntime?.waitUntil) {
        EdgeRuntime.waitUntil(work);
      } else {
        work.catch(() => {});
      }
    } catch {
      work.catch(() => {});
    }
  } catch (error: any) {
    console.warn('[AGENT HOT CALL] Trigger skipped:', error?.message || error);
  }
}

// ─── Centralized Admin Check ─────────────────────────────────────────
// Single source of truth for admin email addresses.
// Used across all endpoints that need admin detection.
// NOTE: Sales reps with @contndr.com emails do NOT have admin access.
// Only the explicit emails listed below have admin privileges.
const ADMIN_EMAILS = ['admin@contndr.com', 'or@roadr.com', 'or@contndr.com'];
const ADMIN_UIDS = ['004b2df9-3e3f-48ec-acfd-5374ab55b09f'];

// ─── Internal / VIP Emails ───────────────────────────────────────────
// These users always get unlimited leads + VIP billing status (bypass payment).
// Includes all @contndr.com emails (admins + sales reps).
// Must mirror the VIP list in contndr-billing.tsx getUserSubscriptionStatus().
const INTERNAL_EMAILS = ['or@roadr.com', 'admin@contndr.com', 'demo@contndr.com', 'axel@redaxemedia.com', 'or@contndr.com'];

function isInternalEmail(email: string | undefined | null): boolean {
  if (!email) return false;
  const e = email.toLowerCase().trim();
  // VIP status: explicit VIPs + all @contndr.com (includes sales reps)
  return INTERNAL_EMAILS.includes(e) || e.endsWith('@contndr.com');
}

// Helper to check if user is internal team member across ALL organization domains
function isInternalTeamMember(email: string | undefined | null): boolean {
  if (!email) return false;
  const e = email.toLowerCase().trim();
  return INTERNAL_EMAILS.includes(e) || 
         e.endsWith('@contndr.com') || 
         e.endsWith('@roadr.com') || 
         e.endsWith('@sourcr.net') || 
         e.endsWith('@covera.co');
}

function isAdminEmail(email: string | undefined | null, uid?: string | undefined | null): boolean {
  if (uid && ADMIN_UIDS.includes(uid)) return true;
  if (!email) return false;
  const e = email.toLowerCase().trim();
  // Auto-resolve UID from the email→uid cache populated by getAuthenticatedUser()
  // This means callers don't need to explicitly pass user.id — the UID check
  // fires automatically for any recently-authenticated user.
  if (!uid) {
    const cachedUid = _recentEmailToUid.get(e);
    if (cachedUid && ADMIN_UIDS.includes(cachedUid)) return true;
  }
  // Only explicit admin emails have admin access - sales reps do NOT
  return ADMIN_EMAILS.includes(e);
}

function isMissingAccessField(value: any): boolean {
  const normalized = String(value || '').trim().toLowerCase();
  return !normalized || ['unknown', 'n/a', 'na', 'none', 'null', 'undefined'].includes(normalized);
}

function validateAccessApplicationFields(fields: Record<string, any>) {
  const requiredFields = [
    ['name', 'Full name'],
    ['email', 'Email'],
    ['phone', 'Phone number'],
    ['company', 'Company'],
    ['businessType', 'Business type'],
    ['monthlyLeadVolume', 'Monthly lead volume'],
    ['teamSize', 'Team size'],
    ['annualRevenue', 'Annual revenue'],
  ] as const;
  return requiredFields
    .filter(([key]) => isMissingAccessField(fields[key]))
    .map(([, label]) => label);
}

// ─── Affiliate Auto-Enrollment Helper ────────────────────────────────
async function ensureAffiliateSlug(user: any): Promise<string> {
  if (isAdminEmail(user.email, user.id)) return '';
  
  // ✅ FIX: Only external users should get affiliate tracking links
  // Sales reps and internal team members should NOT get affiliate slugs
  if (isInternalTeamMember(user.email)) {
    console.log(`[AFFILIATE] Skipping affiliate enrollment for internal team member: ${user.email}`);
    return ''; // No affiliate tracking for internal team
  }
  
  try {
    const affRaw = await kv.get(`affiliate:${user.id}`);
    if (affRaw) {
      const aff = typeof affRaw === 'string' ? JSON.parse(affRaw) : affRaw;
      if (aff.slug) return aff.slug;
    }
    const namePart = (user.user_metadata?.full_name || user.user_metadata?.name || user.email?.split('@')[0] || 'user')
      .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    let slug = namePart || 'rep';
    let existing = await kv.get(`affiliate_slug:${slug}`);
    let a = 0;
    while (existing && a < 10) { slug = `${namePart}-${Math.random().toString(36).substring(2,6)}`; existing = await kv.get(`affiliate_slug:${slug}`); a++; }
    if (!existing) {
      await kv.set(`affiliate:${user.id}`, { slug, userId: user.id, email: user.email, name: user.user_metadata?.full_name || user.user_metadata?.name || user.email, commission_rate: 0.10, status: 'active', created_at: new Date().toISOString(), paypal_email: null, payout_method: 'paypal' });
      await kv.set(`affiliate_slug:${slug}`, user.id);
      await kv.set(`affiliate:${user.id}:referrals`, []);
      console.log(`[AFFILIATE] Auto-enrolled ${user.email} slug: ${slug}`);
      return slug;
    }
  } catch (e) { console.warn('[AFFILIATE] Auto-enroll failed:', e); }
  return '';
}

// Returns the user's current lead count from the DB
async function getUserLeadCount(supabase: ReturnType<typeof createClient>, userId: string): Promise<number> {
  try {
    const { count, error } = await supabase
      .from('leads')
      .select('id', { count: 'estimated', head: true })
      .eq('user_id', userId);
    if (error) {
      console.error('[LEAD LIMIT] Error counting leads for user:', userId, error?.message || error);
      return 0;
    }
    return count || 0;
  } catch (err: any) {
    console.error('[LEAD LIMIT] Exception counting leads for user:', userId, err?.message || err);
    return 0;
  }
}

// Checks if importing `additionalCount` leads would exceed the user's plan limit.
// Returns { allowed, currentCount, limit, plan } — the caller decides what to do.
async function checkLeadLimit(user: any, supabase: ReturnType<typeof createClient>, additionalCount: number = 0) {
  const sub = await getUserSubscriptionStatus(user);
  const plan = sub?.plan || 'none';
  const limit = getLeadLimitForPlan(plan);
  const currentCount = await getUserLeadCount(supabase, user.id);
  const allowed = limit === -1 || (currentCount + additionalCount) <= limit;
  return { allowed, currentCount, limit, plan, remaining: limit === -1 ? -1 : Math.max(0, limit - currentCount) };
}

// Helper: Verify that the authenticated user owns a given lead
// Returns the lead row if found, or null if the user doesn't own the lead
async function verifyLeadOwnership(
  supabase: ReturnType<typeof createClient>,
  leadId: string,
  userId: string
): Promise<any | null> {
  const { data: lead, error } = await supabase
    .from('leads')
    .select('id, user_id')
    .eq('id', leadId)
    .eq('user_id', userId)
    .maybeSingle();

  if (error) {
    console.warn(`[AUTH] Lead ownership check error for lead=${leadId}, user=${userId}:`, error.message);
    return null;
  }
  return lead;
}

// Middleware to protect sensitive sub-apps
// This allows us to disable "Enforce JWT Verification" at the gateway level
// while keeping these specific modules secure.
const protectRoute = async (c: any, next: any) => {
  if (c.req.method === 'OPTIONS') return next();
  
  // Skip protection for webhooks if they are ever added under these paths
  if (c.req.path.includes('/webhooks') || c.req.path.includes('/webhook')) return next();

  try {
    await getAuthenticatedUser(c);
    await next();
  } catch (e: any) {
    const msg = e?.message ?? String(e);
    // If the auth failure was caused by a transient network error (all retries
    // exhausted), return 503 so the frontend knows to retry rather than treating
    // it as a real auth failure that would trigger a logout.
    const isTransient = msg.includes('connection reset') || msg.includes('error sending request')
      || msg.includes('fetch failed') || msg.includes('Failed to fetch')
      || msg.includes('ECONNRESET') || msg.includes('network error')
      || msg.includes('SendRequest') || msg.includes('ConnectionAborted')
      || msg.includes('broken pipe') || msg.includes('client error');
    if (isTransient) {
      console.warn('[protectRoute] Transient network error during auth — returning 503:', msg);
      return c.json({ error: "Temporary service error — please retry" }, 503);
    }
    return c.json({ error: "Unauthorized" }, 401);
  }
};

// Apply protection to sensitive modules
