// ─────────────────────────────────────────────────────────────────────
// GDPR / CCPA endpoints — data export and account deletion.
// These satisfy the "right to portability" (Article 20) and "right to
// erasure" (Article 17) requirements and unblock enterprise security
// questionnaires that explicitly ask for user-initiated deletion.
// ─────────────────────────────────────────────────────────────────────

// GET /account/export — return all user-owned data as a single JSON file.
// Best-effort: every source the backend knows about is collected. The
// response is streamed-as-JSON via c.json() — for very large tenants we
// could later switch to NDJSON streaming, but for now a single payload
// keeps the UX simple ("Download my data" → single .json file).
app.get("/make-server-a8b2511f/account/export", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);
    const userId = user.id;

    // Load all user-scoped DB tables in parallel. Each query is bounded —
    // pathological tenants get truncated rather than OOMing the function.
    const HARD_CAP = 50_000;
    const [
      leads, campaigns, emails, emailEvents, signatures,
      automationRules, followUps, leadGroups,
    ] = await Promise.all([
      supabase.from('leads').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('campaigns').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('emails').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('email_events').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('signatures').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('automation_rules').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('follow_ups').select('*').eq('user_id', userId).limit(HARD_CAP),
      supabase.from('lead_groups').select('*').eq('user_id', userId).limit(HARD_CAP),
    ]);

    // KV-backed records (bounded prefix scans — ignore failures so a single
    // missing prefix doesn't block the whole export).
    const safeKv = async (prefix: string): Promise<any[]> => {
      try { return await kv.getByPrefixLimited(prefix, 5000, 0); } catch { return []; }
    };
    const [
      kvCampaigns, kvAiCalls, kvCompanies, kvVisits,
      kvCredits, kvCreditsLog, kvSubscription, kvSettings,
    ] = await Promise.all([
      safeKv(`campaign:${userId}:`),
      safeKv(`ai_call:${userId}:`),
      safeKv(`company:${userId}:`),
      safeKv(`recent_visit_v2:${userId}:`),
      kv.get(`ai_credits:${userId}`).catch(() => null),
      kv.get(`ai_credits_log:${userId}`).catch(() => null),
      kv.get(`contndr_sub:${userId}`).catch(() => null),
      kv.get(`user_settings:${userId}`).catch(() => null),
    ]);

    const payload = {
      meta: {
        exported_at: new Date().toISOString(),
        user: { id: user.id, email: user.email, created_at: user.created_at },
        format_version: 1,
        notice: 'This export contains all data Contndr stores about you. Some derived caches (e.g. dashboard rollups) are omitted because they are reconstructable from the data above.',
      },
      tables: {
        leads: leads.data || [],
        campaigns: campaigns.data || [],
        emails: emails.data || [],
        email_events: emailEvents.data || [],
        signatures: signatures.data || [],
        automation_rules: automationRules.data || [],
        follow_ups: followUps.data || [],
        lead_groups: leadGroups.data || [],
      },
      kv: {
        campaigns: kvCampaigns,
        ai_calls: kvAiCalls,
        companies: kvCompanies,
        recent_visits: kvVisits,
        ai_credits: kvCredits,
        ai_credits_log: kvCreditsLog,
        subscription: kvSubscription,
        settings: kvSettings,
      },
    };

    c.header('Content-Disposition', `attachment; filename="contndr-export-${user.id}-${new Date().toISOString().split('T')[0]}.json"`);
    c.header('Cache-Control', 'no-store');
    return c.json(payload);
  } catch (error: any) {
    console.error('[ACCOUNT EXPORT] Failed:', error);
    return c.json({ error: error.message || 'Export failed' }, 500);
  }
});

// POST /account/delete — permanently delete the calling user and all their
// data. Requires `confirm: "DELETE"` in the body to prevent accidental
// destruction. This is irreversible.
app.post("/make-server-a8b2511f/account/delete", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);
    const body = await c.req.json().catch(() => ({}));
    if (body?.confirm !== 'DELETE') {
      return c.json({ error: 'Confirmation required. Send {"confirm":"DELETE"} in the body.' }, 400);
    }
    const userId = user.id;
    const userEmail = user.email;

    // Delete DB rows. Best-effort per table — we keep going even if one
    // table fails so the user's footprint is reduced as much as possible.
    // Order matters for FK constraints: child tables before parent tables.
    const dbTables = [
      'lead_emails', 'lead_phones', 'lead_custom_fields',
      'follow_ups', 'campaign_leads', 'group_leads',
      'email_events', 'click_events', 'visitor_events', 'visitor_sessions',
      'admin_events', 'automation_rules',
      'emails', 'campaigns', 'lead_groups', 'signatures',
      'leads', 'leads_new',
    ];
    const dbResults: Record<string, { ok: boolean; error?: string }> = {};
    for (const table of dbTables) {
      try {
        // lead_emails / lead_phones / lead_custom_fields don't have user_id
        // — they cascade through leads.id. Delete by lead_id IN (...).
        if (['lead_emails', 'lead_phones', 'lead_custom_fields'].includes(table)) {
          const { data: ownedLeads } = await supabase.from('leads').select('id').eq('user_id', userId).limit(50000);
          const leadIds = (ownedLeads || []).map((l: any) => l.id);
          if (leadIds.length > 0) {
            await supabase.from(table).delete().in('lead_id', leadIds);
          }
        } else {
          await supabase.from(table).delete().eq('user_id', userId);
        }
        dbResults[table] = { ok: true };
      } catch (e: any) {
        dbResults[table] = { ok: false, error: e.message };
        console.warn(`[ACCOUNT DELETE] Failed to delete from ${table}:`, e.message);
      }
    }

    // Purge KV namespaces tied to this user. Each prefix is scanned in
    // chunks so a tenant with millions of KV rows still finishes.
    const kvPrefixes = [
      `campaign:${userId}:`,
      `ai_call:${userId}:`,
      `ai_call_campaign:${userId}:`,
      `company:${userId}:`,
      `recent_visit_v2:${userId}:`,
      `intent:score:${userId}:`,
      `dashboard:stats:kv:${userId}:`,
      `dashboard:stats:lock:${userId}:`,
      `tracked_sites_index:${userId}`,
      `high_intent_leads:${userId}`,
      `tx_dedup:${userId}:`,
      `ai_lock:${userId}:`,
    ];
    const kvSingleKeys = [
      `contndr_sub:${userId}`,
      `ai_credits:${userId}`,
      `ai_credits_log:${userId}`,
      `ai_credits_lock:${userId}`,
      `user_settings:${userId}`,
      `user:${userId}:team`,
      `gmail_tokens:${userId}`,
      `outlook_tokens:${userId}`,
      `calendly:${userId}`,
      `hubspot:${userId}`,
      `salesforce:${userId}`,
      `quickbooks:${userId}`,
      `affiliate_ref:${userId}`,
      `affiliate:${userId}:referrals`,
      `affiliate_lock:${userId}`,
      `lead_import_lock:${userId}`,
      `stripe_customer:${userId}`,
    ];
    const kvDeleted = { prefixes: 0, keys: 0 };
    for (const prefix of kvPrefixes) {
      try {
        // Drain the prefix in batches of 500
        for (;;) {
          const batch = await kv.getByPrefixLimited(prefix, 500, 0).catch(() => []);
          if (batch.length === 0) break;
          // We need actual key strings, not values. Use a direct Supabase
          // query against the KV table to get keys, then mdel.
          const { createClient } = await import('npm:@supabase/supabase-js@2');
          const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
          const { data: keyRows } = await sb.from('kv_store_a8b2511f').select('key').like('key', `${prefix}%`).limit(500);
          const keys = (keyRows || []).map((r: any) => r.key);
          if (keys.length === 0) break;
          await kv.mdel(keys).catch(() => {});
          kvDeleted.prefixes += keys.length;
          if (keys.length < 500) break;
        }
      } catch (e) {
        console.warn(`[ACCOUNT DELETE] Failed to drain KV prefix ${prefix}:`, e);
      }
    }
    for (const key of kvSingleKeys) {
      try { await kv.del(key); kvDeleted.keys++; } catch {}
    }

    // Finally, delete the auth user. This invalidates all sessions and
    // makes the email re-registrable. Keep a minimal audit trail of the
    // deletion event so support has a record if the user later asks
    // "where did my account go".
    let authDeleteOk = false;
    try {
      const { error: authErr } = await supabase.auth.admin.deleteUser(userId);
      if (authErr) throw authErr;
      authDeleteOk = true;
    } catch (e: any) {
      console.error('[ACCOUNT DELETE] auth.admin.deleteUser failed:', e.message);
    }

    console.log(`[ACCOUNT DELETE] User ${userId} (${userEmail}) self-deleted. DB: ${Object.values(dbResults).filter(r => r.ok).length}/${dbTables.length} tables OK. KV: ${kvDeleted.prefixes + kvDeleted.keys} entries removed. Auth: ${authDeleteOk}`);

    // Record before the auth delete so the actor_id FK still resolves; the
    // SET NULL cascade on actor_id keeps the row intact after the user is gone.
    await recordAuditEvent(c, {
      action: 'account.self_delete',
      resource: 'user',
      resourceId: userId,
      metadata: {
        auth_deleted: authDeleteOk,
        db_tables_ok: Object.values(dbResults).filter(r => r.ok).length,
        kv_entries_removed: kvDeleted.prefixes + kvDeleted.keys,
      },
    });

    return c.json({
      success: true,
      auth_deleted: authDeleteOk,
      db_tables: dbResults,
      kv_entries_removed: kvDeleted.prefixes + kvDeleted.keys,
    });
  } catch (error: any) {
    console.error('[ACCOUNT DELETE] Failed:', error);
    return c.json({ error: error.message || 'Delete failed' }, 500);
  }
});

// GET /user/onboarding - Get onboarding readiness steps
app.get("/make-server-a8b2511f/user/onboarding", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);

    c.header('Cache-Control', 'private, max-age=30, stale-while-revalidate=60');

    // Always build readiness steps from actual user state so the UI
    // can show progress even when re-opened manually via the Setup button.
    const adminDb = getSupabaseAdmin();
    let emailSettings: any = null;
    let signatureRaw: any = null;
    let leadsCount = 0;
    let campaignsCount = 0;

    try {
      const [es, sig, leadsRes, campsRes] = await Promise.all([
        getEmailSettingsFromKV(user.id),
        kv.get(`signature:${user.id}`),
        adminDb.from('leads').select('id', { count: 'estimated', head: true }).eq('user_id', user.id),
        adminDb.from('campaigns').select('id', { count: 'estimated', head: true }).eq('user_id', user.id),
      ]);
      emailSettings = es;
      signatureRaw = sig;
      leadsCount = leadsRes?.count ?? 0;
      campaignsCount = campsRes?.count ?? 0;
    } catch (innerErr: any) {
      console.log('[ONBOARDING] Error fetching readiness data (non-fatal):', innerErr?.message);
      // Continue with defaults — steps will all show as incomplete
    }

    const hasEmail = !!(emailSettings && (emailSettings.provider === 'gmail' || emailSettings.provider === 'outlook' || emailSettings.provider === 'gmail_oauth' || emailSettings.provider === 'outlook_oauth' || emailSettings.smtp_host));
    // Parse signatureRaw — it's stored as a JSON string in KV
    const parsedSig = signatureRaw ? (typeof signatureRaw === 'string' ? (() => { try { return JSON.parse(signatureRaw); } catch { return signatureRaw; } })() : signatureRaw) : null;
    const hasSignature = !!(parsedSig && typeof parsedSig === 'object' && (parsedSig.full_name || parsedSig.name || parsedSig.custom_html || parsedSig.html));
    const hasLeads = leadsCount > 0;
    const hasCampaign = campaignsCount > 0;

    // Check if user has added any tracked websites
    // Uses fast index path first to avoid LIKE query 57014 timeouts
    let hasTracking = false;
    try {
      const siteIndex = await getTrackedSitesIndex(user.id);
      if (siteIndex && siteIndex.length > 0) {
        hasTracking = true;
      } else {
        // Fallback to LIKE-based prefix query with retry
        const trackedSites = await kvGetByPrefixSafe(`tracked_site:${user.id}:`, []);
        hasTracking = trackedSites.length > 0;
        // If we found sites via prefix but no index existed, rebuild it
        if (hasTracking) {
          const siteIds = trackedSites.filter(Boolean).map((s: any) => s.id).filter(Boolean);
          setTrackedSitesIndex(user.id, siteIds).catch(() => {});
        }
      }
    } catch (trackErr: any) {
      console.log('[ONBOARDING] Error checking tracked sites (non-fatal):', trackErr?.message);
    }

    const steps = [
      { id: 'email', label: 'Connect Email', completed: hasEmail },
      { id: 'signature', label: 'Set Up Signature', completed: hasSignature },
      { id: 'tracking', label: 'Website Tracking', completed: hasTracking },
      { id: 'leads', label: 'Import Leads', completed: hasLeads, detail: leadsCount },
      { id: 'campaign', label: 'Send First Campaign', completed: hasCampaign, detail: campaignsCount },
    ];

    const allDone = steps.every(s => s.completed);
    if (allDone) {
      await kv.set(`user_onboarding:${user.id}`, { completed: true });
    }

    // Always return steps so the UI can display them
    return c.json({ completed: allDone, steps });
  } catch (error: any) {
    console.log('[ONBOARDING] Error:', error?.message);
    return c.json({ error: error?.message || 'Unknown error' }, 401);
  }
});

// POST /user/onboarding - Update onboarding progress
app.post("/make-server-a8b2511f/user/onboarding", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    const body = await c.req.json();
    
    // If completed is explicitly true, mark as complete
    if (body.completed) {
        await kv.set(`user_onboarding:${user.id}`, { 
            completed: true, 
            completed_at: new Date().toISOString() 
        });
    } else if (typeof body.step === 'number') {
        // Update progress step
        await kv.set(`user_onboarding:${user.id}`, { 
            completed: false, 
            step: body.step,
            last_updated: new Date().toISOString()
        });
    }
    
    return c.json({ success: true });
  } catch (error) {
    return c.json({ error: error.message }, 401);
  }
});

// GET /user/account-readiness - Check real account readiness for sending campaigns
app.get("/make-server-a8b2511f/user/account-readiness", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);

    // 1. Email provider configured? Use the shared helper from oauth-email.tsx
    const emailSettings = await getEmailSettingsFromKV(user.id);
    const provider = emailSettings.provider;
    const connectedEmail = emailSettings.connected_email;
    // Check if a real email provider (Gmail/Outlook/SMTP) is actually connected.
    // Admin Resend fallback doesn't count for setup — users should explicitly connect a provider.
    const emailReady = provider !== 'resend' && !!connectedEmail;

    // 2. Signature configured?
    const sigRaw = await kv.get(`signature:${user.id}`);
    let hasSignature = false;
    if (sigRaw) {
      try {
        const sig = JSON.parse(sigRaw);
        hasSignature = !!(sig.full_name && sig.full_name.trim());
      } catch { hasSignature = false; }
    }

    // 3. Has leads?
    const { count: leadCount } = await supabase
      .from('leads')
      .select('id', { count: 'estimated', head: true })
      .eq('user_id', user.id);

    const hasLeads = (leadCount || 0) > 0;

    // 4. Has campaigns?
    const { count: campaignCount } = await supabase
      .from('campaigns')
      .select('id', { count: 'estimated', head: true })
      .eq('user_id', user.id);

    const hasCampaigns = (campaignCount || 0) > 0;

    const steps = [
      { id: 'email', label: 'Email Provider', completed: emailReady, detail: provider || 'resend' },
      { id: 'signature', label: 'Email Signature', completed: hasSignature },
      { id: 'leads', label: 'Import Leads', completed: hasLeads, detail: leadCount || 0 },
      { id: 'campaign', label: 'First Campaign', completed: hasCampaigns, detail: campaignCount || 0 },
    ];

    const completedCount = steps.filter(s => s.completed).length;
    const readyToSend = emailReady && hasSignature && hasLeads;

    return c.json({
      steps,
      completedCount,
      totalSteps: steps.length,
      percentage: Math.round((completedCount / steps.length) * 100),
      readyToSend,
      connectedEmail,
    });
  } catch (error: any) {
    console.error('[READINESS] Error checking account readiness:', error);
    return c.json({ error: error.message }, 401);
  }
});

// POST /user/avatar - Upload avatar image
app.post("/make-server-a8b2511f/user/avatar", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);
    const formData = await c.req.formData();
    const file = formData.get('file');

    if (!file || !(file instanceof File)) {
      return c.json({ error: 'No file uploaded' }, 400);
    }

    if (file.size > 5 * 1024 * 1024) { // 5MB limit
      return c.json({ error: 'File size too large (max 5MB)' }, 400);
    }

    const fileExt = file.name.split('.').pop();
    const fileName = `${user.id}-${Date.now()}.${fileExt}`;
    const filePath = `avatars/${fileName}`;

    // Ensure bucket exists (private by default as per instructions)
    const bucketName = 'make-a8b2511f';
    const { data: buckets } = await supabase.storage.listBuckets();
    if (!buckets?.some(b => b.name === bucketName)) {
      await supabase.storage.createBucket(bucketName);
    }

    // Upload file
    const { error: uploadError } = await supabase.storage
      .from(bucketName)
      .upload(filePath, file, {
        contentType: file.type,
        upsert: true
      });

    if (uploadError) {
      throw uploadError;
    }

    // Get signed URL (valid for 10 years essentially, or handle refresh in frontend)
    // Since we can't easily refresh in frontend without logic, let's set a long expiry.
    // 365 days = 31536000 seconds
    const { data: signedUrlData, error: signError } = await supabase.storage
      .from(bucketName)
      .createSignedUrl(filePath, 315360000); // 10 years

    if (signError) {
      throw signError;
    }

    // Update user metadata with the new avatar URL
    await supabase.auth.admin.updateUserById(user.id, {
      user_metadata: { avatar_url: signedUrlData.signedUrl }
    });

    return c.json({ 
      success: true, 
      url: signedUrlData.signedUrl 
    });

  } catch (error) {
    console.error('[AVATAR] Upload error:', error);
    return c.json({ error: error.message }, 500);
  }
});

// POST /contact - Save contact form submission
app.post("/make-server-a8b2511f/contact", async (c) => {
  try {
    const body = await c.req.json();
    const { name, email, company, message } = body;
    
    if (!email || !message) {
      return c.json({ error: "Email and message are required" }, 400);
    }
    
    // Validate email
    if (!isValidBusinessEmail(email)) {
       // We still accept it but flag it? Or just allow it.
       // For a contact form, we should probably be permissive.
    }
    
    const submissionId = crypto.randomUUID();
    const submission = {
      id: submissionId,
      name: name || '',
      email,
      company: company || '',
      message,
      created_at: new Date().toISOString(),
      status: 'new'
    };
    
    // Store in KV store
    // We'll store a list of submission IDs in a 'contact_submissions' key
    // AND store the actual submission in `contact:${id}`
    
    // 1. Store the individual submission
    await kv.set(`contact:${submissionId}`, submission);
    
    // 2. Update the list (fetch, append, set)
    // Note: KV store operations are not atomic, so race conditions are possible under high load.
    // Given the expected volume, this is acceptable.
    const listKey = 'contact_submissions_list';
    const existingList = (await kv.get(listKey)) || [];
    await kv.set(listKey, [submissionId, ...existingList].slice(0, 1000)); // Keep last 1000
    
    console.log(`[CONTACT] New submission from ${email} (${submissionId})`);
    
    return c.json({ success: true, message: "Message received" });
  } catch (error) {
    console.error('[CONTACT] Error processing submission:', error);
    return c.json({ error: error.message }, 500);
  }
});

// POST /waitlist - Join the priority access waitlist
app.post("/make-server-a8b2511f/waitlist", async (c) => {
  try {
    const body = await c.req.json();
    const { name, email, phone, company, businessType, monthlyLeadVolume, teamSize, annualRevenue } = body;

    const missingFields = validateAccessApplicationFields({
      name,
      email,
      phone,
      company,
      businessType,
      monthlyLeadVolume,
      teamSize,
      annualRevenue,
    });
    if (missingFields.length > 0) {
      return c.json({
        error: `Complete your access application before continuing. Missing: ${missingFields.join(', ')}`,
        missingFields,
      }, 400);
    }

    // Check for duplicate email
    const existing = await kv.get(`waitlist:email:${email.toLowerCase()}`);
    if (existing) {
      return c.json({ error: "You're already on the waitlist! We'll reach out soon." }, 409);
    }

    const entryId = crypto.randomUUID();
    const entry = {
      id: entryId,
      name,
      email: email.toLowerCase(),
      phone,
      company,
      businessType,
      monthlyLeadVolume,
      teamSize,
      annualRevenue,
      created_at: new Date().toISOString(),
      status: 'pending',
    };

    // Store entry
    await kv.set(`waitlist:${entryId}`, entry);
    // Index by email for dedup
    await kv.set(`waitlist:email:${email.toLowerCase()}`, entryId);

    // Update the ordered list
    const listKey = 'waitlist_entries_list';
    const existingList = (await kv.get(listKey)) || [];
    await kv.set(listKey, [entryId, ...existingList].slice(0, 5000));

    // Update count
    const countKey = 'waitlist_count';
    const currentCount = (await kv.get(countKey)) || 127; // Base count
    await kv.set(countKey, currentCount + 1);

    console.log(`[WAITLIST] New entry from ${email} - ${phone} - ${businessType} - ${monthlyLeadVolume} (${entryId})`);

    // Log admin event
    logAdminEvent('waitlist_join', 'New Waitlist Entry', `${name} (${email}) joined the waitlist — ${businessType || 'Unknown business'}`, {
      email: email.toLowerCase(),
      metadata: { name, phone, company, businessType, monthlyLeadVolume, teamSize, annualRevenue, position: currentCount + 1 }
    }).catch(() => {});

    // Send confirmation email
    try {
      await sendWaitlistConfirmation(email, name);
    } catch (emailErr) {
      console.error('[WAITLIST] Failed to send confirmation email:', emailErr);
      // Don't fail the request if email fails
    }

    return c.json({ success: true, position: currentCount + 1 });
  } catch (error) {
    console.error('[WAITLIST] Error processing waitlist entry:', error);
    return c.json({ error: error.message }, 500);
  }
});

// POST /admin/waitlist/approve - Approve a waitlist entry and send invite
app.post("/make-server-a8b2511f/admin/waitlist/approve", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    if (!isAdminEmail(user.email)) {
      return c.json({ error: 'Unauthorized' }, 403);
    }
    
    const { id, email } = await c.req.json();
    
    // Update waitlist entry
    let entry = await kv.get(`waitlist:${id}`);
    if (!entry) {
       // If not found by ID, try email
       const waitlistId = await kv.get(`waitlist:email:${email.toLowerCase()}`);
       if (waitlistId) {
          entry = await kv.get(`waitlist:${waitlistId}`);
       }
    }
    
    if (entry) {
       console.log(`[ADMIN] Found waitlist entry for ${email}, current status: ${entry.status}`);
       entry.status = 'approved';
       entry.approved_at = new Date().toISOString();
       await kv.set(`waitlist:${entry.id}`, entry);
       console.log(`[ADMIN] Updated waitlist status to 'approved' for entry ${entry.id}`);
       
       // Don't update subscription status here - billing service will detect
       // approval status and show paywall on next login
       console.log(`[ADMIN] User approved - will see paywall on next login`);
    } else {
       console.log(`[ADMIN] No waitlist entry found for ${email}, creating one`);
       // Create a new entry if doesn't exist
       const newEntryId = crypto.randomUUID();
       entry = {
         id: newEntryId,
         email: email.toLowerCase(),
         name: 'Approved User',
         status: 'approved',
         approved_at: new Date().toISOString(),
         created_at: new Date().toISOString(),
         source: 'admin_approval'
       };
       await kv.set(`waitlist:${newEntryId}`, entry);
       await kv.set(`waitlist:email:${email.toLowerCase()}`, newEntryId);
       console.log(`[ADMIN] Created new approved waitlist entry ${newEntryId}`);
    }
    
    // Approval unlocks the subscription screen, not product access. Clear legacy
    // approval whitelist keys so approved users cannot bypass billing.
    await kv.del(`whitelist:${email.toLowerCase()}`).catch((legacyErr: any) => {
      console.warn('[ADMIN] Could not clear legacy waitlist whitelist key:', legacyErr?.message || legacyErr);
    });

    // Log admin event
    logAdminEvent('waitlist_approved', 'User Approved', `${entry?.name || email} was approved and invited`, {
      email: email.toLowerCase(),
      metadata: { name: entry?.name, approvedBy: user.email }
    }).catch(() => {});
    
    // Send invite email
    let emailWarning: string | undefined;
    try {
      await sendInviteEmail(email, entry?.name || 'there');
    } catch (e) {
      console.error('[ADMIN] Failed to send invite email:', e);
      emailWarning = 'Approved but email failed to send';
    }

    // Realtime fan-out: notify the user's own channel + the admin channel
    // so the user's pending screen flips immediately AND any open admin
    // dashboard refreshes without a manual reload.
    (async () => {
      try {
        const { notifyUserStatusChange } = await import('./realtime-broadcast.tsx');
        const targetUserId = entry?.userId || null;
        if (targetUserId) {
          await notifyUserStatusChange({
            userId: targetUserId,
            email: email.toLowerCase(),
            newStatus: 'approved',
            source: 'admin_waitlist_approve',
          });
        }
      } catch (e) { console.warn('[REALTIME] approve broadcast failed:', (e as any)?.message); }
    })();

    return c.json({ success: true, ...(emailWarning ? { warning: emailWarning } : {}) });
  } catch (error) {
    console.error('[ADMIN] Error approving user:', error);
    return c.json({ error: error.message }, 500);
  }
});

// POST /admin/waitlist/reject - Reject a waitlist entry
app.post("/make-server-a8b2511f/admin/waitlist/reject", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    if (!isAdminEmail(user.email)) {
      return c.json({ error: 'Unauthorized' }, 403);
    }
    
    const { id } = await c.req.json();
    
    const entry = await kv.get(`waitlist:${id}`);
    if (entry) {
       entry.status = 'rejected';
       await kv.set(`waitlist:${id}`, entry);
    }
    
    // Also remove from whitelist if present
    if (entry?.email) {
       await kv.del(`whitelist:${entry.email.toLowerCase()}`);
    }

    // Realtime fan-out
    (async () => {
      try {
        const { notifyUserStatusChange } = await import('./realtime-broadcast.tsx');
        if (entry?.userId) {
          await notifyUserStatusChange({
            userId: entry.userId,
            email: entry.email,
            newStatus: 'rejected',
            source: 'admin_waitlist_reject',
          });
        }
      } catch (e) { console.warn('[REALTIME] reject broadcast failed:', (e as any)?.message); }
    })();

    return c.json({ success: true });
  } catch (error) {
    console.error('[ADMIN] Error rejecting user:', error);
    return c.json({ error: error.message }, 500);
  }
});

// GET /waitlist/count - Get current waitlist stats
app.get("/make-server-a8b2511f/waitlist/count", async (c) => {
  try {
    const count = (await kv.get('waitlist_count')) || 127;
    // Spots left cycles weekly: 25 base, minus entries this week
    const spotsLeft = Math.max(3, 25 - (count % 25));
    c.header('Cache-Control', 'public, max-age=60, stale-while-revalidate=120');
    return c.json({ count, spotsLeft });
  } catch (error) {
    console.error('[WAITLIST] Error getting count:', error);
    return c.json({ count: 127, spotsLeft: 18 });
  }
});

// GET /admin/waitlist - Get all waitlist entries (Admin Only)
app.get("/make-server-a8b2511f/admin/waitlist", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    
    // Admin check
    if (!isAdminEmail(user.email)) {
      return c.json({ error: 'Unauthorized: Admin access required' }, 403);
    }
    
    const allValues = await kv.getByPrefixLimited('waitlist:', 1000, 0);

    const isMissingWaitlistValue = (value: any) => {
      const normalized = String(value || '').trim().toLowerCase();
      return !normalized || ['unknown', 'n/a', 'na', 'none', 'null', 'undefined'].includes(normalized);
    };

    const authUsersByEmail = new Map<string, any>();
    try {
      const supabase = getSupabaseAdmin();
      const { data } = await supabase.auth.admin.listUsers({ page: 1, perPage: 1000 });
      for (const authUser of data?.users || []) {
        const email = authUser.email?.toLowerCase().trim();
        if (email) authUsersByEmail.set(email, authUser);
      }
    } catch (userErr: any) {
      console.warn('[ADMIN] Could not enrich waitlist from auth users:', userErr?.message || userErr);
    }

    const rawEntries = allValues.filter(v =>
      typeof v === 'object' && 
      v !== null && 
      v.email && 
      v.id && 
      v.status
    );

    const enrichedEntries = rawEntries.map((entry: any) => {
      const email = String(entry.email || '').toLowerCase().trim();
      const authUser = authUsersByEmail.get(email);
      const meta = authUser?.user_metadata || {};
      return {
        ...entry,
        email,
        userId: entry.userId || authUser?.id,
        name: !isMissingWaitlistValue(entry.name) && !['User', 'OAuth User', 'Approved User'].includes(String(entry.name).trim())
          ? entry.name
          : (meta.full_name || meta.name || meta.user_name || entry.name || email),
        phone: entry.phone || meta.phone || '',
        company: entry.company || meta.brand || meta.company || meta.organization || '',
        businessType: !isMissingWaitlistValue(entry.businessType) ? entry.businessType : (meta.businessType || ''),
        monthlyLeadVolume: !isMissingWaitlistValue(entry.monthlyLeadVolume) ? entry.monthlyLeadVolume : (meta.monthlyLeadVolume || ''),
        teamSize: !isMissingWaitlistValue(entry.teamSize) ? entry.teamSize : (meta.teamSize || ''),
        annualRevenue: !isMissingWaitlistValue(entry.annualRevenue) ? entry.annualRevenue : (meta.annualRevenue || ''),
        created_at: entry.created_at || authUser?.created_at || new Date().toISOString(),
      };
    });

    const statusRank = (status: string) => {
      if (['approved', 'signed_up'].includes(status)) return 4;
      if (status === 'pending_signup') return 3;
      if (status === 'pending') return 2;
      if (['rejected', 'declined'].includes(status)) return 1;
      return 0;
    };
    const entryScore = (entry: any) =>
      statusRank(entry.status) +
      (isMissingWaitlistValue(entry.businessType) ? 0 : 3) +
      (isMissingWaitlistValue(entry.monthlyLeadVolume) ? 0 : 3) +
      (isMissingWaitlistValue(entry.teamSize) ? 0 : 1) +
      (isMissingWaitlistValue(entry.annualRevenue) ? 0 : 1) +
      (entry.phone ? 1 : 0);

    const byEmail = new Map<string, any>();
    for (const entry of enrichedEntries) {
      const existing = byEmail.get(entry.email);
      const entryTime = new Date(entry.created_at || 0).getTime();
      const existingTime = new Date(existing?.created_at || 0).getTime();
      const score = entryScore(entry);
      const existingScore = existing ? entryScore(existing) : -1;
      if (!existing || score > existingScore || (score === existingScore && entryTime > existingTime)) {
        byEmail.set(entry.email, entry);
      }
    }

    const entries = Array.from(byEmail.values())
      .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

    // Self-heal the email index and ordered list so older duplicate KV rows stop
    // resurfacing through legacy code paths.
    await Promise.allSettled(entries.map((entry: any) => kv.set(`waitlist:email:${entry.email}`, entry.id)));
    try {
      const listKey = 'waitlist_entries_list';
      const existingList = (await kv.get(listKey)) || [];
      const canonicalIds = new Set(entries.map((entry: any) => entry.id));
      const cleanedList = [
        ...entries.map((entry: any) => entry.id),
        ...existingList.filter((id: string) => canonicalIds.has(id)),
      ];
      await kv.set(listKey, [...new Set(cleanedList)].slice(0, 5000));
    } catch (listErr: any) {
      console.warn('[ADMIN] Waitlist list cleanup failed:', listErr?.message || listErr);
    }

    c.header('Cache-Control', 'private, max-age=20, stale-while-revalidate=60');
    return c.json({ entries });
  } catch (error) {
    console.error('[ADMIN] Error fetching waitlist:', error);
    return c.json({ error: error.message }, 500);
  }
});

