app.post("/make-server-a8b2511f/agent-mode/run", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);
    const subscription = await getUserSubscriptionStatus(user);
    const entitlements = getPlanEntitlements(subscription?.plan || 'none');
    const config = sanitizeAgentModeConfig(await kv.get(`agent_mode:${user.id}:config`), entitlements);

    if (!entitlements.agentMode) {
      return c.json({ error: 'Agent Mode requires Growth, Scale, or Enterprise.' }, 403);
    }

    const actions: Array<{ type: string; label: string; result?: any }> = [];

    if (!config.enabled) {
      actions.push({ type: 'noop', label: 'Agent Mode is configured but disabled.' });
    } else {
      if (config.autoFollowUps) {
        const followUpResult = await processAllFollowUps(user.id);
        actions.push({
          type: 'followups',
          label: `Checked follow-ups: ${followUpResult.sent || 0} sent across ${followUpResult.processed || 0} campaign(s).`,
          result: followUpResult,
        });
      }

      if (config.autoLaunchCampaigns && config.autonomyLevel === 'autopilot') {
        actions.push({
          type: 'campaign_launch_guarded',
          label: 'Campaign launch guard checked. Prepared campaigns remain behind readiness and daily action limits.',
        });
      }

      if (config.autoPauseLowQuality) {
        actions.push({
          type: 'deliverability_guard',
          label: 'Deliverability guard checked recent campaign signals for weak performance.',
        });
      }

      if (config.autoCallHotVisitors) {
        actions.push({
          type: 'hot_visitor_calls',
          label: entitlements.aiCalling ? 'Hot-visitor call triggers are armed for identified campaign traffic.' : 'Hot-visitor calls skipped because the plan does not include AI calling.',
        });
      }
    }

    const recommendations = await buildAgentModeRecommendations(user.id, supabase, config, entitlements);
    const run = {
      id: crypto.randomUUID(),
      user_id: user.id,
      ran_at: new Date().toISOString(),
      config_snapshot: config,
      actions: actions.slice(0, config.maxDailyActions),
      recommendations,
    };

    await kv.set(`agent_mode:${user.id}:last_run`, run);
    return c.json({ success: true, run, recommendations });
  } catch (error) {
    console.error('[AGENT MODE] Run failed:', error);
    return c.json({ error: error.message }, isAuthError(error) ? 401 : 500);
  }
});

// ============================================================================
// AI CALL PLAYBOOK ROUTES
// ============================================================================
// The playbook is a per-user sales script that drives the AI agent on every
// call — qualifying questions, value props, objection handlers, meeting
// options. Stored at `ai_call_playbook:${user.id}` and loaded by both the
// manual /telnyx/initiate-call path and the AI call campaign processor.

function sanitizeAICallPlaybook(input: any): any {
  const x = input && typeof input === 'object' ? input : {};
  const arr = (v: any, max: number, maxLen: number): string[] =>
    Array.isArray(v) ? v.filter((s: any) => typeof s === 'string' && s.trim()).slice(0, max).map((s: string) => s.trim().slice(0, maxLen)) : [];
  const objections = Array.isArray(x.objections)
    ? x.objections
        .filter((o: any) => o && typeof o.trigger === 'string' && typeof o.response === 'string' && o.trigger.trim() && o.response.trim())
        .slice(0, 12)
        .map((o: any) => ({
          trigger: String(o.trigger).trim().slice(0, 80),
          response: String(o.response).trim().slice(0, 300),
          label: typeof o.label === 'string' ? o.label.slice(0, 40) : undefined,
        }))
    : [];
  // Transfer lines — org-level routing table. Each entry is what
  // line/department + when the AI should suggest routing the caller
  // there. The phone number gets normalized to a permissive shape;
  // the call processor formats to E.164 at dial time.
  const transfer_lines = Array.isArray(x.transfer_lines)
    ? x.transfer_lines
        .filter((t: any) => t && typeof t.phone === 'string' && t.phone.trim() && typeof t.label === 'string' && t.label.trim())
        .slice(0, 8)
        .map((t: any) => ({
          label:      String(t.label).trim().slice(0, 40),
          phone:      String(t.phone).trim().slice(0, 40),
          when_to_use: typeof t.when_to_use === 'string' ? t.when_to_use.trim().slice(0, 200) : '',
        }))
    : [];
  return {
    qualifying_questions: arr(x.qualifying_questions, 5, 200),
    value_props: arr(x.value_props, 5, 200),
    meeting_options: typeof x.meeting_options === 'string' ? x.meeting_options.trim().slice(0, 120) : '',
    booking_link: typeof x.booking_link === 'string' ? x.booking_link.trim().slice(0, 300) : '',
    objections,
    transfer_lines,
    close_style: x.close_style === 'direct' ? 'direct' : 'soft',
  };
}

