// ============================================================================
// TODAY — Home-screen aggregator
// ============================================================================
// Surfaces the 3–5 things that matter RIGHT NOW: hot visitors on site,
// unread replies, calls happening today, active campaigns. All in one
// parallel call so the home screen feels instant.
//
// Design rule: zero-counts are returned (not omitted) so the frontend can
// show "All caught up" instead of jankily mounting cards as data arrives.

app.get("/make-server-a8b2511f/today", async (c) => {
  try {
    const { user, supabase } = await getAuthenticatedUser(c);
    // Opportunistic: activate due-scheduled campaigns (60s cooldown, fire-and-forget)
    maybeRunScheduledTrigger().catch(() => {});
    const userId = user.id;
    const nowMs = Date.now();
    const HOT_WINDOW_MIN = 10; // visitor counts as "on site now" if seen in last 10 min
    const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0);

    // Run everything in parallel — fail-soft on any individual source.
    // Added sources beyond the original 4 (visitors / replies /
    // campaigns / calls): newly-created leads today, closed-won deals
    // today, recent bounces (deliverability signal), scheduled campaigns
    // about to fire, and the user's own subscription status (for
    // payment-failed nudges).
    const last24hIso = new Date(nowMs - 24 * 60 * 60 * 1000).toISOString();
    const todayStartIso = todayStart.toISOString();

    const [
      visitsRaw,
      repliedEmailsRes,
      activeCampaignsRes,
      scheduledCampaignsRes,
      allCallsRaw,
      newLeadsRes,
      dealsWonRes,
      bouncesRes,
      subRecordRaw,
    ] = await Promise.all([
      kvGetByPrefixSafe(`recent_visit_v2:${userId}:`, []).catch(() => []),
      supabase
        .from('emails')
        .select('id, lead_id, from_email, from_name, subject, snippet, body, received_at, replied_at, user_replied_at, status, direction')
        .eq('user_id', userId)
        .in('status', ['replied'])
        .order('updated_at', { ascending: false })
        .limit(50)
        .then((r: any) => r).catch(() => ({ data: [], error: null })),
      supabase
        .from('campaigns')
        .select('id, name, brand, status, total_recipients, sent_count, delivered_count, created_at, updated_at')
        .eq('user_id', userId)
        .in('status', ['active', 'sending'])
        .order('updated_at', { ascending: false })
        .limit(20)
        .then((r: any) => r).catch(() => ({ data: [], error: null })),
      supabase
        .from('campaigns')
        .select('id, name, scheduled_at')
        .eq('user_id', userId)
        .eq('status', 'scheduled')
        .gte('scheduled_at', new Date(nowMs).toISOString())
        .lte('scheduled_at', new Date(nowMs + 24 * 60 * 60 * 1000).toISOString())
        .order('scheduled_at', { ascending: true })
        .limit(10)
        .then((r: any) => r).catch(() => ({ data: [], error: null })),
      kv.getByPrefixLimited('call:', 1000, 0).catch(() => []),
      supabase
        .from('leads')
        .select('id', { count: 'exact', head: true })
        .eq('user_id', userId)
        .gte('created_at', todayStartIso)
        .then((r: any) => r).catch(() => ({ count: 0, error: null })),
      // Closed-won pipeline deals today (table name and column may differ;
      // fail-soft so missing schema doesn't break the rest of the panel).
      supabase
        .from('pipeline_deals')
        .select('id, name, amount, stage, customer_name, updated_at')
        .eq('user_id', userId)
        .eq('stage', 'closed_won')
        .gte('updated_at', todayStartIso)
        .order('updated_at', { ascending: false })
        .limit(10)
        .then((r: any) => r).catch(() => ({ data: [], error: null })),
      supabase
        .from('emails')
        .select('id', { count: 'exact', head: true })
        .eq('user_id', userId)
        .eq('status', 'bounced')
        .gte('updated_at', last24hIso)
        .then((r: any) => r).catch(() => ({ count: 0, error: null })),
      kv.get(`contndr_sub:${userId}`).catch(() => null),
    ]);

    // ── Hot visitors on site right now ──
    // Identified (has lead_id) + seen within HOT_WINDOW_MIN minutes.
    // Skip "infrastructure" URLs that aren't real page visits — the
    // tracking pixel sometimes records hits to /functions/v1/.../unsubscribe/<token>
    // when a recipient clicks the unsubscribe link, which then surfaces
    // as a "Known visitor on /functions/v1/..." entry. Filter those out
    // so the panel only shows actual marketing page visits.
    const isMeaningfulPage = (urlOrPath: string): boolean => {
      const p = (urlOrPath || '').toLowerCase();
      if (!p) return false;
      if (p.includes('/functions/v1/')) return false;
      if (p.includes('/unsubscribe/'))   return false;
      if (p.includes('/track/open/'))    return false;
      if (p.includes('/track/click/'))   return false;
      if (p.includes('/api/'))           return false;
      if (p.endsWith('.png') || p.endsWith('.jpg') || p.endsWith('.gif') || p.endsWith('.ico')) return false;
      return true;
    };
    const hotCutoff = nowMs - HOT_WINDOW_MIN * 60_000;
    const hotMap = new Map<string, any>();
    for (const v of (visitsRaw as any[])) {
      if (!v || !v.lead_id || v.lead_id === 'anonymous') continue;
      const ts = v.timestamp ? new Date(v.timestamp).getTime() : 0;
      if (ts < hotCutoff) continue;
      if (!isMeaningfulPage(v.url || '')) continue;
      const prev = hotMap.get(v.lead_id);
      if (!prev || (prev._ts || 0) < ts) {
        let page = '';
        try { page = new URL(v.url || '').pathname || '/'; } catch { page = v.url || ''; }
        hotMap.set(v.lead_id, {
          lead_id: v.lead_id,
          name: v.lead_name || v.contact_name || v.business_name || 'Known visitor',
          business: v.business_name || '',
          page,
          last_seen_ms_ago: nowMs - ts,
          _ts: ts,
        });
      }
    }
    const hotList = [...hotMap.values()]
      .sort((a, b) => a.last_seen_ms_ago - b.last_seen_ms_ago)
      .slice(0, 5)
      .map(({ _ts, ...rest }) => rest);

    // ── Unread replies ──
    // Email status flipped to 'replied' (inbound), and the user hasn't sent
    // an outbound to the same lead since. Best-effort heuristic: status is
    // 'replied' and user_replied_at is null/missing.
    const repliedRows = (repliedEmailsRes.data || []) as any[];
    const unreadReplies = repliedRows
      .filter((e: any) => !e.user_replied_at)
      .slice(0, 5)
      .map((e: any) => ({
        email_id: e.id,
        lead_id: e.lead_id,
        from_name: e.from_name || (e.from_email ? e.from_email.split('@')[0] : 'Lead'),
        from_email: e.from_email || '',
        subject: e.subject || '(no subject)',
        snippet: (e.snippet || e.body || '').toString().slice(0, 140),
        received_at: e.replied_at || e.received_at || e.updated_at,
      }));
    const unreadCount = repliedRows.filter((e: any) => !e.user_replied_at).length;

    // ── Active campaigns sending ──
    const campaigns = (activeCampaignsRes.data || []) as any[];
    const campaignSummaries = campaigns.slice(0, 5).map((c: any) => ({
      id: c.id,
      name: c.name,
      brand: c.brand,
      status: c.status,
      sent: c.sent_count || 0,
      total: c.total_recipients || 0,
    }));

    // ── AI calls today ──
    const myCallsToday = (allCallsRaw as any[]).filter((cc: any) =>
      cc && (cc.user_id === userId || cc.ai_config?.user_id === userId) &&
      cc.started_at && new Date(cc.started_at).getTime() >= todayStart.getTime()
    );
    const connectedToday = myCallsToday.filter((cc: any) =>
      !!cc.answered_at || ['answered', 'speaking', 'listening', 'processing', 'completed', 'ended', 'voicemail'].includes(cc.status)
    ).length;
    const activeNow = myCallsToday.filter((cc: any) =>
      ['initiated', 'ringing', 'answered', 'speaking', 'listening', 'processing'].includes(cc.status)
    ).length;

    // ── New leads added today (by you or your team) ──
    const newLeadsCount = Number((newLeadsRes as any)?.count || 0);

    // ── Deals closed-won today ──
    const dealsWon = ((dealsWonRes as any)?.data || []) as any[];
    const dealsWonItems = dealsWon.slice(0, 5).map((d: any) => ({
      id: d.id,
      name: d.name || d.customer_name || 'Deal',
      customer: d.customer_name || '',
      amount: typeof d.amount === 'number' ? d.amount : Number(d.amount) || 0,
    }));
    const dealsWonTotal = dealsWon.reduce((s: number, d: any) => {
      const n = typeof d.amount === 'number' ? d.amount : Number(d.amount) || 0;
      return s + n;
    }, 0);

    // ── Bounce spike in last 24h (deliverability risk) ──
    const bouncesLast24h = Number((bouncesRes as any)?.count || 0);

    // ── Scheduled campaigns about to fire (next 24h) ──
    const scheduledSoon = ((scheduledCampaignsRes as any)?.data || []) as any[];
    const scheduledItems = scheduledSoon.slice(0, 5).map((s: any) => ({
      id: s.id,
      name: s.name,
      scheduled_at: s.scheduled_at,
    }));

    // ── Subscription / payment health (only nudge when there's a problem) ──
    const sub = (subRecordRaw as any) || {};
    const paymentTrouble = ['past_due', 'unpaid', 'incomplete', 'incomplete_expired'].includes(sub.status);

    c.header('Cache-Control', 'no-store');
    return c.json({
      success: true,
      generated_at: new Date(nowMs).toISOString(),
      hot_visitors_now: { count: hotList.length, top: hotList },
      unread_replies: { count: unreadCount, top: unreadReplies },
      campaigns_sending: { count: campaigns.length, items: campaignSummaries },
      ai_calls_today: {
        total: myCallsToday.length,
        connected: connectedToday,
        active_now: activeNow,
      },
      new_leads_today: { count: newLeadsCount },
      deals_won_today: {
        count: dealsWon.length,
        total_amount: dealsWonTotal,
        items: dealsWonItems,
      },
      bounces_last_24h: { count: bouncesLast24h },
      scheduled_soon: { count: scheduledSoon.length, items: scheduledItems },
      payment_alert: paymentTrouble ? { status: sub.status } : null,
    });
  } catch (error: any) {
    console.error('[TODAY] Aggregator failed:', error);
    return c.json({ error: error.message }, isAuthError(error) ? 401 : 500);
  }
});

// ============================================================================
// AI BRAIN — Voice & Tone defaults (user-level)
// ============================================================================
// Stored at `ai_brain:${user.id}:voice`. Surfaced in the "AI Brain → Voice &
// Tone" tab. Pre-fills campaign builders and provides defaults for the
// auto-call synthetic campaign and ElevenLabs Convai agent prompts.

function sanitizeAIVoice(input: any): any {
  const x = input && typeof input === 'object' ? input : {};
  const allowedTone = ['friendly', 'professional', 'direct', 'confident'];
  return {
    ai_name: typeof x.ai_name === 'string' ? x.ai_name.trim().slice(0, 40) : '',
    brand: typeof x.brand === 'string' ? x.brand.trim().slice(0, 60) : '',
    tone: allowedTone.includes(x.tone) ? x.tone : 'friendly',
    voice_id: typeof x.voice_id === 'string' ? x.voice_id.trim().slice(0, 60) : 'rachel',
    filler_words: x.filler_words !== false,
  };
}

app.get("/make-server-a8b2511f/ai-brain/voice", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    const voice = await kv.get(`ai_brain:${user.id}:voice`);
    c.header('Cache-Control', 'no-store');
    return c.json({ success: true, voice: voice || sanitizeAIVoice(null) });
  } catch (error: any) {
    console.error('[AI BRAIN VOICE] Load failed:', error);
    return c.json({ error: error.message }, isAuthError(error) ? 401 : 500);
  }
});

app.put("/make-server-a8b2511f/ai-brain/voice", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    const body = await c.req.json().catch(() => ({}));
    const voice = sanitizeAIVoice(body);
    await kv.set(`ai_brain:${user.id}:voice`, {
      ...voice,
      updated_at: new Date().toISOString(),
      updated_by: user.email || user.id,
    });
    c.header('Cache-Control', 'no-store');
    return c.json({ success: true, voice });
  } catch (error: any) {
    console.error('[AI BRAIN VOICE] Save failed:', error);
    return c.json({ error: error.message }, isAuthError(error) ? 401 : 500);
  }
});

// ============================================================================
// AI CALL — TEST MODE
// ============================================================================
// One-click "Call me with a fake prospect" button. Bypasses cooldowns, daily
// caps, lead-existence, and entitlement checks. Uses the user's own profile
// as the synthetic lead so they can hear the full pipeline (TTS, KB,
// playbook, opening line) end-to-end without touching real leads.
//
// Why this exists: features without a one-click "prove it works" path don't
// get trusted. Half of our prior debugging was "is the auto-call pipeline
// even reachable?" — this answers that in 10 seconds.

app.post("/make-server-a8b2511f/ai-call/test-call", async (c) => {
  try {
    const { user } = await getAuthenticatedUser(c);
    const body = await c.req.json().catch(() => ({}));
    const toNumber: string = String(body?.phone || user.user_metadata?.phone || '').trim();
    if (!toNumber) {
      return c.json({
        success: false,
        error: 'No phone number provided. Save a phone in your Profile or pass `phone` in the request body.',
      }, 400);
    }

    // Pull the user's playbook + KB so the test reflects their real config
    let playbook: any = null;
    try { playbook = await kv.get(`ai_call_playbook:${user.id}`); } catch {}

    // ── Layer B: route through ElevenLabs Conversational AI if enabled ──
    // When user has Convai toggle ON and registered their Telnyx number in
    // the ElevenLabs portal, calls bypass our Telnyx + STT + GPT + TTS
    // polling pipeline entirely. ElevenLabs handles the full conversation
    // in a single streaming pipeline (~400ms end-to-end latency vs ~3s on
    // the polling path).
    const agentModeConfig = sanitizeAgentModeConfig(
      await kv.get(`agent_mode:${user.id}:config`),
      { agentMode: true, aiCalling: true, intentAutoCall: true } // entitlements ignored for test call
    );
    const routeDecisionMsg = `useElevenLabsConvai=${agentModeConfig.useElevenLabsConvai}, elevenLabsPhoneNumberId=${agentModeConfig.elevenLabsPhoneNumberId || '(empty)'}`;
    console.log(`[TEST CALL] Route decision: ${routeDecisionMsg}`);
    if (!agentModeConfig.useElevenLabsConvai || !agentModeConfig.elevenLabsPhoneNumberId) {
      // Surface the reason in the toast so the user knows WHY Convai was skipped.
      // Don't error out — fall through to Telnyx path below.
      console.log(`[TEST CALL] Skipping Convai → ${!agentModeConfig.useElevenLabsConvai ? 'toggle is OFF' : 'phone_number_id is empty'}`);
    }
    let convaiFailureReason: string | null = null;
    if (agentModeConfig.useElevenLabsConvai && agentModeConfig.elevenLabsPhoneNumberId) {
      console.log(`[TEST CALL · CONVAI] Routing through ElevenLabs Convai with phone_number_id=${agentModeConfig.elevenLabsPhoneNumberId}`);
      try {
        const { syncAgentForCall } = await import('./elevenlabs.tsx');
        // Push fresh playbook + KB + lead context into the agent BEFORE
        // we dial. The agent will use this prompt for the entire call.
        const userName = user.user_metadata?.full_name || user.user_metadata?.name || (user.email || 'You').split('@')[0];
        const synced = await syncAgentForCall({
          userId: user.id,
          userEmail: user.email || undefined,
          ai_config: {
            name: 'Alex',
            brand: 'Contndr',
            objective: 'book_call',
            brand_tone: 'friendly',
          },
          lead: {
            name: userName,
            business: 'Test Prospect',
            email: user.email,
            phone: toNumber,
          },
        });
        if (!synced.synced) {
          throw new Error(`Agent sync failed: ${synced.error}`);
        }

        const apiKey = Deno.env.get('ELEVENLABS_API_KEY');
        if (!apiKey) throw new Error('ELEVENLABS_API_KEY not configured');

        const convaiRes = await fetch('https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call', {
          method: 'POST',
          headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            agent_id: synced.agent_id,
            agent_phone_number_id: agentModeConfig.elevenLabsPhoneNumberId,
            to_number: toNumber,
          }),
        });
        const convaiJson = await convaiRes.json().catch(() => ({}));
        if (!convaiRes.ok || !convaiJson.success) {
          throw new Error(`ElevenLabs Convai outbound failed (${convaiRes.status}): ${convaiJson.message || JSON.stringify(convaiJson).slice(0, 200)}`);
        }

        console.log(`[TEST CALL · CONVAI] User ${user.email || user.id} → ${toNumber} | conversation=${convaiJson.conversation_id} sip=${convaiJson.sip_call_id}`);

        // ── Write a call:* record so this conversation appears in the
        // AI Calls dashboard. The ElevenLabs post-call webhook (handler
        // in elevenlabs.tsx) will later fill in transcript + outcome.
        const convaiCallId = `convai_${Date.now()}_${crypto.randomUUID().slice(0, 8)}`;
        const userNameForCall = user.user_metadata?.full_name || user.user_metadata?.name || (user.email || 'You').split('@')[0];
        const convaiCallRecord = {
          id: convaiCallId,
          user_id: user.id,
          route: 'elevenlabs_convai',
          convai_conversation_id: convaiJson.conversation_id || null,
          convai_sip_call_id: convaiJson.sip_call_id || null,
          status: 'answered', // ConvAI calls go straight to connected
          answered_at: new Date().toISOString(),
          started_at: new Date().toISOString(),
          to_number: toNumber,
          from_number: '',
          lead_name: userNameForCall,
          business_name: 'Test Prospect',
          ai_name: 'Alex',
          brand: 'contndr',
          _test_call: true,
        };
        await kv.set(`call:${convaiCallId}`, convaiCallRecord).catch(() => {});
        // Reverse index so the post-call webhook can find this record
        // when ElevenLabs delivers the transcript by conversation_id.
        if (convaiJson.conversation_id) {
          await kv.set(`call_by_convai:${convaiJson.conversation_id}`, convaiCallId).catch(() => {});
        }

        return c.json({
          success: true,
          route: 'elevenlabs_convai',
          call_id: convaiCallId,
          conversation_id: convaiJson.conversation_id,
          sip_call_id: convaiJson.sip_call_id,
          to: toNumber,
          message: `ElevenLabs is dialing ${toNumber} now. Sub-second response latency. Conversation: ${convaiJson.conversation_id || '?'}.`,
        });
      } catch (convaiErr: any) {
        convaiFailureReason = String(convaiErr?.message || convaiErr).slice(0, 300);
        console.error('[TEST CALL · CONVAI] Failed, falling back to Telnyx path:', convaiFailureReason);
        // Fall through to legacy Telnyx path below
      }
    }

    // Find the first active AI call campaign as a script source (same logic
    // as the hot-visitor auto-call). If none, defaults flow through.
    const campaigns = await kv.getByPrefixLimited(`ai-call-campaign:${user.id}:`, 50, 0).catch(() => []);
    const scriptSource = (campaigns || []).find((c: any) =>
      c && c.status === 'active' && !String(c.id || '').startsWith('agent-hot-') && !String(c.id || '').startsWith('test-call-')
    ) || null;

    const now = Date.now();
    const callCampaignId = `test-call-${now}-${crypto.randomUUID().slice(0, 8)}`;
    const userName = user.user_metadata?.full_name || user.user_metadata?.name || (user.email || 'You').split('@')[0];
    const testLead = {
      id: `test-lead-${user.id}`,
      email: user.email || `test+${user.id}@contndr.com`,
      phone: toNumber,
      contact_name: userName,
      business_name: scriptSource?.brand || 'Test Prospect',
      first_name: userName.split(' ')[0],
      _is_test_lead: true,
    };

    const campaign = {
      ...(scriptSource || {}),
      id: callCampaignId,
      parent_campaign_id: scriptSource?.id || null,
      name: `🧪 Test call to ${userName}`,
      status: 'active',
      brand: scriptSource?.brand || 'contndr',
      ai_name: scriptSource?.ai_name || 'Alex',
      opening_line: scriptSource?.opening_line || '',
      voice_id: scriptSource?.voice_id || 'rachel',
      knowledge_base: scriptSource?.knowledge_base || '',
      playbook: playbook || null,
      selected_leads: [testLead],
      total_leads: 1,
      calls_made: 0,
      in_progress: 0,
      completed_calls: 0,
      trigger_source: 'test_call',
      _test_call: true,
      _test_call_initiator: user.id,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };

    await kv.set(`ai-call-campaign:${user.id}:${callCampaignId}`, campaign);
    console.log(`[TEST CALL] User ${user.email || user.id} firing test call to ${toNumber}`);

    // Fire the processor without awaiting — same pattern as hot-visitor auto-call
    const work = processAICallCampaign(callCampaignId, user.id, campaign).catch((error: any) => {
      console.error('[TEST CALL] Processor error:', error?.message || error);
    });
    try {
      if (typeof EdgeRuntime !== 'undefined' && EdgeRuntime?.waitUntil) {
        EdgeRuntime.waitUntil(work);
      }
    } catch {}

    // Build a clear "why didn't Convai fire" reason for the toast.
    const convaiSkipReason = !agentModeConfig.useElevenLabsConvai
      ? 'toggle is OFF'
      : !agentModeConfig.elevenLabsPhoneNumberId
        ? 'phone number ID is empty'
        : convaiFailureReason || 'Convai attempt failed silently (check function logs)';
    return c.json({
      success: true,
      route: 'telnyx_legacy',
      convai_skip_reason: convaiSkipReason,
      campaign_id: callCampaignId,
      to: toNumber,
      using_playbook: !!playbook,
      using_kb: !!campaign.knowledge_base,
      message: `Calling ${toNumber} via Telnyx (Convai skipped: ${convaiSkipReason}).`,
    });
  } catch (error: any) {
    console.error('[TEST CALL] Failed:', error);
    return c.json({ success: false, error: error.message }, isAuthError(error) ? 401 : 500);
  }
});

